BEGIN;
CREATE TABLE inbound_email_intent (
    tenant_id          uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    inbound_email_id   bigint NOT NULL,
    intent_class       text NOT NULL CHECK (intent_class IN ('question','praise','unsub','ooo','other')),
    intent_confidence  numeric(4,3) NOT NULL DEFAULT 0,
    classifier         text NOT NULL DEFAULT 'ai' CHECK (classifier IN ('ai','heuristic','manual')),
    classified_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, inbound_email_id)
);
CREATE INDEX inbound_email_intent_class_idx
    ON inbound_email_intent (tenant_id, intent_class, classified_at DESC);
GRANT SELECT, INSERT, UPDATE, DELETE ON inbound_email_intent TO postwave_app;
ALTER TABLE inbound_email_intent ENABLE ROW LEVEL SECURITY;
ALTER TABLE inbound_email_intent FORCE  ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON inbound_email_intent
    AS RESTRICTIVE FOR ALL
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
COMMIT;

specs.api_contract:
GET /api/v1/campaigns/{id}/replies?intent={question|praise|unsub|ooo|other}&limit={1..200}
  scope: ScopeReadCampaigns
  200 { items: Reply[] }
  Reply: { id: string (inbound_emails.id stringified), campaign_id: string, subscriber_id: string, from_email: string, subject: string, body_text_excerpt: string, received_at: RFC3339, intent_class: 'question'|'praise'|'unsub'|'ooo'|'other'|'', intent_confidence: number, intent_classified_at: RFC3339|null, classifier: 'ai'|'heuristic'|'manual'|'' }
  400 { code: 'invalid_intent', message } on unknown intent value
  401 { code: 'no_tenant', message }

GET /api/v1/campaigns/{id}/replies/{reply_id}
  scope: ScopeReadCampaigns
  200 Reply & { body_text: string, body_html_sanitized: string, message_id: string, in_reply_to: string }
  404 { code: 'not_found' }

POST /api/v1/campaigns/{id}/replies/{reply_id}/classify
  scope: ScopeWriteCampaigns
  body: {} (server reads the inbound row)
  200 Reply (with intent_class + intent_confidence + classifier populated)
  404 { code: 'not_found' }
  503 { code: 'classifier_unavailable', message } — feature flag off OR voice service down; row left unclassified
  Audit: writes 'campaigns.reply_classified' on success with payload { reply_id, intent_class, confidence, classifier }.

