CREATE TABLE IF NOT EXISTS campaign_ai_summaries (
  campaign_id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  generated_at timestamptz NOT NULL DEFAULT now(),
  model text NOT NULL,
  source text NOT NULL CHECK (source IN ('llm','deterministic')),
  headline text NOT NULL,
  narrative text NOT NULL,
  snapshot jsonb NOT NULL,
  suggestions jsonb NOT NULL DEFAULT '[]',
  baseline_days int NOT NULL DEFAULT 30,
  baseline_sample_size int NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_campaign_ai_summaries_tenant ON campaign_ai_summaries(tenant_id, generated_at DESC);
ALTER TABLE campaign_ai_summaries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_visible ON campaign_ai_summaries;
CREATE POLICY tenant_visible ON campaign_ai_summaries AS PERMISSIVE FOR ALL TO postwave_app
  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

BEGIN;
ALTER TABLE campaigns
    ADD COLUMN IF NOT EXISTS window_start timestamptz,
    ADD COLUMN IF NOT EXISTS window_end   timestamptz,
    ADD COLUMN IF NOT EXISTS per_recipient_optimize boolean NOT NULL DEFAULT false;
ALTER TABLE campaigns
    ADD CONSTRAINT campaigns_psto_window_chk
    CHECK (NOT per_recipient_optimize
           OR (window_start IS NOT NULL
               AND window_end IS NOT NULL
               AND window_end > window_start));
ALTER TABLE campaign_recipients
    ADD COLUMN IF NOT EXISTS scheduled_send_at timestamptz;
COMMIT;
-- Outside tx: partial index, indexing only the in-flight subset stays tiny.
CREATE INDEX CONCURRENTLY IF NOT EXISTS campaign_recipients_pending_due_idx
    ON campaign_recipients (campaign_id, scheduled_send_at NULLS FIRST)
    WHERE status = 'pending';
-- Existing tenant_isolation RLS on both tables already covers new columns; no policy changes.

BEGIN;

-- Per-tenant frequency cap rules. Empty table = no caps applied.
CREATE TABLE frequency_cap_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  label text NOT NULL DEFAULT '',
  max_sends int NOT NULL CHECK (max_sends > 0),
  window_hours int NOT NULL CHECK (window_hours BETWEEN 1 AND 720),
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX frequency_cap_rules_tenant_idx ON frequency_cap_rules(tenant_id) WHERE active;
GRANT SELECT,INSERT,UPDATE,DELETE ON frequency_cap_rules TO postwave_app;
ALTER TABLE frequency_cap_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE frequency_cap_rules FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON frequency_cap_rules AS RESTRICTIVE FOR ALL
  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- Per-recipient send counter source-of-truth.
CREATE TABLE subscriber_send_log (
  id bigserial PRIMARY KEY,
  tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  subscriber_email citext NOT NULL,
  campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  sent_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX subscriber_send_log_lookup_idx ON subscriber_send_log(tenant_id, subscriber_email, sent_at DESC);
GRANT SELECT,INSERT,DELETE ON subscriber_send_log TO postwave_app;
GRANT USAGE,SELECT ON SEQUENCE subscriber_send_log_id_seq TO postwave_app;
ALTER TABLE subscriber_send_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscriber_send_log FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON subscriber_send_log AS RESTRICTIVE FOR ALL
  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- Per-campaign filter outcome summary so /report can read counters without re-scanning.
CREATE TABLE campaign_filter_summaries (
  campaign_id uuid PRIMARY KEY REFERENCES campaigns(id) ON DELETE CASCADE,
  tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  skipped_frequency_cap int NOT NULL DEFAULT 0,
  deferred_quiet_hours int NOT NULL DEFAULT 0,
  breakdown jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT,INSERT,UPDATE,DELETE ON campaign_filter_summaries TO postwave_app;
ALTER TABLE campaign_filter_summaries ENABLE ROW LEVEL SECURITY;
ALTER TABLE campaign_filter_summaries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON campaign_filter_summaries AS RESTRICTIVE FOR ALL
  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- Extend tenant_sending_settings with the per-recipient TZ switch.
ALTER TABLE tenant_sending_settings
  ADD COLUMN IF NOT EXISTS quiet_hours_per_recipient boolean NOT NULL DEFAULT false;

COMMIT;

