    campaign_id, status, recipients_queued: int,
    recipients_skipped_frequency_cap: int,
    recipients_deferred_quiet_hours: int,
    frequency_skip_breakdown: [{ rule_id, rule_label, skipped: int }],
    approval_id?, approval_status?, sandbox?
  }

GET /api/v1/campaigns/{id}/report (existing — response extended)
  200: { …existing fields…,
    recipients_skipped_frequency_cap: int,
    recipients_deferred_quiet_hours: int,
    frequency_skip_breakdown: [{ rule_id, rule_label, skipped }]
  }

POST /api/v1/subject-lab/variants
  Scope: write_campaigns
  Body: { "seed_subject": "string>=10", "axis": "length|emoji|question|personalization", "count": 5..8 default 6, "voice_profile_id"?: uuid, "body_excerpt"?: "string<=2000" }
  200: { "variants": ["..."], "axis": "string", "generated_at": "RFC3339" }
  Errors: 400 bad_request, 401 no_tenant, 503 voice_unavailable, 502 compose_failed

POST /api/v1/subject-lab/score
